import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

import { afterEach, describe, expect, it, vi } from "vitest";

import { resolveRuntimeInput } from "./runtime-input.js";

const temporaryDirectories: string[] = [];

async function temporaryPath(name: string): Promise<string> {
	const directory = await fs.promises.mkdtemp(path.join(os.tmpdir(), "notion-workers-input-"));
	temporaryDirectories.push(directory);
	return path.join(directory, name);
}

afterEach(async () => {
	vi.unstubAllEnvs();
	await Promise.all(
		temporaryDirectories.splice(0).map((directory) =>
			fs.promises.rm(directory, {
				recursive: true,
				force: true,
			}),
		),
	);
});

describe("resolveRuntimeInput", () => {
	it("falls back to the argument when the input payload path is not configured", async () => {
		vi.stubEnv("NOTION_INPUT_PAYLOAD_PATH", undefined);
		const fallback = { source: "argument" };

		await expect(resolveRuntimeInput(fallback)).resolves.toBe(fallback);
	});

	it("falls back to the argument when the input file is absent", async () => {
		const inputPath = await temporaryPath("missing.json");
		const fallback = { source: "argument" };
		vi.stubEnv("NOTION_INPUT_PAYLOAD_PATH", inputPath);

		await expect(resolveRuntimeInput(fallback)).resolves.toBe(fallback);
	});

	it("reads a multi-megabyte JSON value from the input file", async () => {
		const inputPath = await temporaryPath("input.json");
		const fileInput = { source: "file", payload: "x".repeat(3 * 1024 * 1024) };
		await fs.promises.writeFile(inputPath, JSON.stringify(fileInput));
		vi.stubEnv("NOTION_INPUT_PAYLOAD_PATH", inputPath);

		const resolved = await resolveRuntimeInput({ source: "argument", payload: "" });

		expect(resolved).toEqual(fileInput);
	});

	it("does not fall back when the input file contains malformed JSON", async () => {
		const inputPath = await temporaryPath("input.json");
		await fs.promises.writeFile(inputPath, "{");
		vi.stubEnv("NOTION_INPUT_PAYLOAD_PATH", inputPath);

		await expect(resolveRuntimeInput({ source: "argument" })).rejects.toBeInstanceOf(SyntaxError);
	});

	it("does not fall back for input file read failures other than ENOENT", async () => {
		const inputPath = await temporaryPath("input.json");
		await fs.promises.mkdir(inputPath);
		vi.stubEnv("NOTION_INPUT_PAYLOAD_PATH", inputPath);

		await expect(resolveRuntimeInput({ source: "argument" })).rejects.toMatchObject({
			code: "EISDIR",
		});
	});
});
